rows = [item["json"] for item in _items]

columns = [
    "Units_Sold",
    "Unit_Price",
    "Discount",
    "Advertising_Spend",
    "Revenue",
    "Profit",
    "Customer_Satisfaction"
]

stats = {}

for col in columns:
    values = []

    for row in rows:
        try:
            v = row.get(col)
            if v is not None and v != "":
                values.append(float(v))
        except:
            pass

    values.sort()

    n = len(values)

    if n > 0:
        total = 0
        for v in values:
            total += v

        mean = total / n

        if n % 2 == 1:
            median = values[n // 2]
        else:
            median = (values[n // 2 - 1] + values[n // 2]) / 2

        squared_sum = 0

        for v in values:
            squared_sum += (v - mean) ** 2

        if n > 1:
            standard_deviation = (squared_sum / (n - 1)) ** 0.5
        else:
            standard_deviation = 0

        stats[col] = {
            "count": n,
            "mean": round(mean, 2),
            "median": round(median, 2),
            "standard_deviation": round(standard_deviation, 2),
            "minimum": round(values[0], 2),
            "maximum": round(values[-1], 2)
        }


def get_correlation(col1, col2):

    x = []
    y = []

    for row in rows:
        try:
            a = row.get(col1)
            b = row.get(col2)

            if a is not None and b is not None:
                x.append(float(a))
                y.append(float(b))
        except:
            pass

    n = len(x)

    if n < 2:
        return None

    mean_x = sum(x) / n
    mean_y = sum(y) / n

    numerator = 0
    sum_x = 0
    sum_y = 0

    for i in range(n):
        dx = x[i] - mean_x
        dy = y[i] - mean_y

        numerator += dx * dy
        sum_x += dx ** 2
        sum_y += dy ** 2

    denominator = (sum_x * sum_y) ** 0.5

    if denominator == 0:
        return None

    return round(numerator / denominator, 3)


pairs = [
    ("Units_Sold", "Revenue"),
    ("Unit_Price", "Revenue"),
    ("Revenue", "Profit"),
    ("Advertising_Spend", "Profit"),
    ("Discount", "Revenue"),
    ("Unit_Price", "Profit")
]

correlations = {}

for col1, col2 in pairs:
    correlations[col1 + " vs " + col2] = get_correlation(col1, col2)


return [{
    "json": {
        "total_clean_rows": len(rows),
        "descriptive_statistics": stats,
        "correlations": correlations
    }
}]

# Machine Learning: Profit Prediction using Linear Regression
# No external libraries required

rows = [item["json"] for item in _items]

features = [
    "Units_Sold",
    "Unit_Price",
    "Discount",
    "Advertising_Spend",
    "Customer_Satisfaction"
]

target = "Profit"

data = []

for row in rows:
    try:
        x = [float(row[f]) for f in features]
        y = float(row[target])
        data.append((x, y))
    except:
        pass

n = len(data)

if n < 10:
    return [{
        "json": {
            "ml_status": "error",
            "message": "Not enough valid rows for machine learning",
            "rows_available": n
        }
    }]

# 80/20 train-test split
train_size = int(n * 0.8)

train = data[:train_size]
test = data[train_size:]

X_train = [x for x, y in train]
y_train = [y for x, y in train]

X_test = [x for x, y in test]
y_test = [y for x, y in test]


# Add intercept column
X = []

for row in X_train:
    X.append([1.0] + row)


# Matrix multiplication
def transpose(A):
    return list(map(list, zip(*A)))


def multiply(A, B):
    result = []

    for i in range(len(A)):
        row = []

        for j in range(len(B[0])):
            value = 0

            for k in range(len(B)):
                value += A[i][k] * B[k][j]

            row.append(value)

        result.append(row)

    return result


# Matrix inverse using Gauss-Jordan elimination
def inverse(A):

    n = len(A)

    identity = []

    for i in range(n):
        row = []

        for j in range(n):
            if i == j:
                row.append(1.0)
            else:
                row.append(0.0)

        identity.append(row)

    augmented = []

    for i in range(n):
        augmented.append(A[i] + identity[i])

    for i in range(n):

        pivot = augmented[i][i]

        if abs(pivot) < 1e-12:

            swap = None

            for r in range(i + 1, n):

                if abs(augmented[r][i]) > 1e-12:
                    swap = r
                    break

            if swap is None:
                return None

            augmented[i], augmented[swap] = augmented[swap], augmented[i]

            pivot = augmented[i][i]

        for j in range(2 * n):
            augmented[i][j] /= pivot

        for r in range(n):

            if r != i:

                factor = augmented[r][i]

                for j in range(2 * n):
                    augmented[r][j] -= factor * augmented[i][j]

    result = []

    for i in range(n):
        result.append(augmented[i][n:])

    return result


# Convert y into column matrix
Y = []

for value in y_train:
    Y.append([value])


# X'X
XT = transpose(X)

XTX = multiply(XT, X)

XTX_inverse = inverse(XTX)

if XTX_inverse is None:

    return [{
        "json": {
            "ml_status": "error",
            "message": "Could not calculate regression coefficients"
        }
    }]


# X'Y
XTY = multiply(XT, Y)

# Regression coefficients
B = multiply(XTX_inverse, XTY)

coefficients = [round(row[0], 6) for row in B]


# Prediction function
def predict(x):

    value = coefficients[0]

    for i in range(len(x)):
        value += coefficients[i + 1] * x[i]

    return value


predictions = []

for x in X_test:

    predictions.append(predict(x))


# MAE
absolute_errors = []

for actual, predicted in zip(y_test, predictions):

    absolute_errors.append(abs(actual - predicted))

mae = sum(absolute_errors) / len(absolute_errors)


# RMSE
squared_errors = []

for actual, predicted in zip(y_test, predictions):

    squared_errors.append((actual - predicted) ** 2)

rmse = (sum(squared_errors) / len(squared_errors)) ** 0.5


# R-squared
mean_y = sum(y_test) / len(y_test)

ss_total = 0
ss_residual = 0

for actual, predicted in zip(y_test, predictions):

    ss_total += (actual - mean_y) ** 2
    ss_residual += (actual - predicted) ** 2

if ss_total == 0:
    r_squared = 0
else:
    r_squared = 1 - (ss_residual / ss_total)


# Return ML results
return [{
    "json": {
        "ml_status": "success",
        "model": "Multiple Linear Regression",
        "target": target,
        "features": features,
        "total_rows": n,
        "training_rows": len(train),
        "testing_rows": len(test),
        "coefficients": {
            features[i]: coefficients[i + 1]
            for i in range(len(features))
        },
        "intercept": coefficients[0],
        "evaluation": {
            "MAE": round(mae, 2),
            "RMSE": round(rmse, 2),
            "R_squared": round(r_squared, 4)
        },
        "sample_predictions": [
            {
                "actual_profit": round(y_test[i], 2),
                "predicted_profit": round(predictions[i], 2)
            }
            for i in range(min(10, len(predictions)))
        ]
    }
}]

