report = _items[0]["json"].get("final_report", "")

# Remove accidental leading "="
while report.startswith("="):
    report = report[1:]

report = report.strip()


def esc(text):
    text = str(text)
    text = text.replace("&", "&amp;")
    text = text.replace("<", "&lt;")
    text = text.replace(">", "&gt;")
    return text


def fmt(text):
    text = esc(text)

    # Bold
    result = ""
    i = 0

    while i < len(text):
        if i + 1 < len(text) and text[i:i+2] == "**":
            end = text.find("**", i + 2)

            if end != -1:
                result += "<strong>" + text[i+2:end] + "</strong>"
                i = end + 2
                continue

        result += text[i]
        i += 1

    text = result

    # Italic
    result = ""
    i = 0

    while i < len(text):
        if text[i] == "*" and not (
            i + 1 < len(text) and text[i+1] == "*"
        ):
            end = text.find("*", i + 1)

            if end != -1:
                result += "<em>" + text[i+1:end] + "</em>"
                i = end + 1
                continue

        result += text[i]
        i += 1

    return result


def parse_table_row(line):
    line = line.strip()

    if not line.startswith("|"):
        return []

    if line.endswith("|"):
        line = line[1:-1]
    else:
        line = line[1:]

    return [cell.strip() for cell in line.split("|")]


def is_separator(row):
    if not row:
        return False

    for cell in row:
        cell = cell.replace(":", "").replace("-", "").strip()

        if cell != "":
            return False

    return True


lines = report.splitlines()
html = []

i = 0

while i < len(lines):

    line = lines[i].strip()

    if line == "":
        i += 1
        continue

    # Headings
    if line.startswith("### "):
        html.append("<h3>" + fmt(line[4:]) + "</h3>")
        i += 1
        continue

    if line.startswith("## "):
        html.append("<h2>" + fmt(line[3:]) + "</h2>")
        i += 1
        continue

    if line.startswith("# "):
        html.append("<h1>" + fmt(line[2:]) + "</h1>")
        i += 1
        continue

    # TABLE
    if line.startswith("|"):

        first_row = parse_table_row(line)

        if (
            i + 1 < len(lines)
            and lines[i + 1].strip().startswith("|")
        ):

            second_row = parse_table_row(lines[i + 1].strip())

            if is_separator(second_row):

                headers = first_row
                rows = []

                i += 2

                while i < len(lines):

                    current = lines[i].strip()

                    if not current.startswith("|"):
                        break

                    row = parse_table_row(current)

                    if row:
                        rows.append(row)

                    i += 1

                table = "<table>"
                table += "<thead><tr>"

                for header in headers:
                    table += "<th>" + fmt(header) + "</th>"

                table += "</tr></thead>"
                table += "<tbody>"

                for row in rows:

                    table += "<tr>"

                    for j in range(len(headers)):

                        if j < len(row):
                            value = row[j]
                        else:
                            value = ""

                        table += "<td>" + fmt(value) + "</td>"

                    table += "</tr>"

                table += "</tbody></table>"

                html.append(table)

                continue

    # Numbered list
    if (
        len(line) > 2
        and line[0].isdigit()
        and line[1:3] == ". "
    ):

        items = []
        number = 1

        while i < len(lines):

            current = lines[i].strip()

            if (
                len(current) > 2
                and current[0].isdigit()
                and ". " in current[:4]
            ):

                dot = current.find(". ")

                if dot != -1:
                    items.append(
                        "<li>" +
                        fmt(current[dot + 2:]) +
                        "</li>"
                    )

                    i += 1
                    number += 1
                    continue

            break

        html.append("<ol>" + "".join(items) + "</ol>")
        continue

    # Bullet list
    if line.startswith("- ") or line.startswith("* "):

        items = []

        while i < len(lines):

            current = lines[i].strip()

            if current.startswith("- ") or current.startswith("* "):

                items.append(
                    "<li>" + fmt(current[2:]) + "</li>"
                )

                i += 1

            else:
                break

        html.append("<ul>" + "".join(items) + "</ul>")
        continue

    # Horizontal rule
    if line == "---":
        html.append("<hr>")
        i += 1
        continue

    # Normal paragraph
    paragraph = [line]
    i += 1

    while i < len(lines):

        nxt = lines[i].strip()

        if nxt == "":
            break

        if nxt.startswith("# "):
            break

        if nxt.startswith("## "):
            break

        if nxt.startswith("### "):
            break

        if nxt.startswith("|"):
            break

        if nxt.startswith("- "):
            break

        if nxt.startswith("* "):
            break

        if len(nxt) > 2 and nxt[0].isdigit() and ". " in nxt[:4]:
            break

        paragraph.append(nxt)
        i += 1

    html.append(
        "<p>" + fmt(" ".join(paragraph)) + "</p>"
    )


final_report_html = "\n".join(html)

return [{
    "json": {
        "final_report": report,
        "final_report_html": final_report_html
    }
}]
